mapper.delete:
delete a,b,c,e from iot_linkage_item a
    inner join iot_linkage_condition b on a.id=b.linkage_item_id
    inner join iot_linkage_action c on a.id=c.linkage_item_id
    inner join iot_linkage_condition_item e on e.linkage_condition_id=b.id
where a.id in (

    #{itemId}
);

delete a,b,c,d,e from iot_linkage a
    inner join iot_linkage_condition b on a.id=b.linkage_id
    inner join iot_linkage_action c on a.id=c.linkage_id
    inner join iot_linkage_item d on a.id=d.linkage_id
    inner join iot_linkage_condition_item e on e.linkage_condition_id=b.id
where a.id in (

    #{linkageId}
);

mapper.select:
select a.*, es.name event_source_name, es.product_ids, es.status event_source_status, es.device_group_ids source_device_group_ids from iot_linkage a
    left join iot_event_source es on a.event_source_id = es.id
where a.id=#{id}

select a.*, es.name event_source_name, es.status event_source_status from iot_linkage a
    left join iot_event_source es on a.event_source_id = es.id


        and a.status = #{entity.status}


        and a.event_source_id=#{entity.eventSourceId}


        and a.name like '%${entity.name}%'


order by a.create_time desc
